package org.circus.core;

import java.io.*;
import java.util.*;
import java.util.zip.InflaterInputStream;

/** Actual current-image path/extension instruction outputs; only the OS
 *attribute query is an explicit fixture. Complete destination/stale suffix,
 *input aliases, root mutations and query ordering are compared. */
public final class Pc1NativePathsTests {
    private static int count;
    private static void check(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
    private static byte[] blob(DataInput in)throws IOException{int length=in.readInt();if(length<0||length>1024*1024)throw new IOException("fixture length");byte[] b=new byte[length];in.readFully(b);return b;}
    private static final class Region {final int address;final byte[] bytes;Region(int address,byte[] bytes){this.address=address;this.bytes=bytes;}}
    private static final class Memory implements Pc1NativePaths.Memory {
        final List<Region> regions=new ArrayList<>();
        public int read(int address)throws IOException{for(Region r:regions){long at=(address&0xffffffffL)-(r.address&0xffffffffL);if(at>=0&&at<r.bytes.length)return r.bytes[(int)at]&255;}throw new IOException("unowned path byte"+Integer.toHexString(address));}
        public void write(int address,int value)throws IOException{for(Region r:regions){long at=(address&0xffffffffL)-(r.address&0xffffffffL);if(at>=0&&at<r.bytes.length){r.bytes[(int)at]=(byte)value;return;}}throw new IOException("unowned path byte"+Integer.toHexString(address));}
        byte[] bytes(int address,int length)throws IOException{byte[] b=new byte[length];for(int n=0;n<length;n++)b[n]=(byte)read(address+n);return b;}
        byte[] cstring(int address)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int n=0;n<65536;n++){int value=read(address+n);if(value==0)return b.toByteArray();b.write(value);}throw new IOException("fixture scan");}
    }
    public static int run()throws Exception{
        count=0;StringBuilder text=new StringBuilder();for(String part:VECTORS)text.append(part);
        DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(text.toString()))));int programs=in.readInt();
        for(int n=0;n<programs;n++){
            String id=new String(blob(in),"UTF-8");int entry=in.readInt();int[] args=new int[4];for(int k=0;k<4;k++)args[k]=in.readInt();final int attributes=in.readInt();Memory memory=new Memory();int regions=in.readInt();
            for(int k=0;k<regions;k++)memory.regions.add(new Region(in.readInt(),blob(in)));
            memory.regions.add(new Region(Pc1NativePaths.DATA_PREFIX,new byte[]{'\\','A','d','v','D','a','t','a','\\',0}));memory.regions.add(new Region(Pc1NativePaths.SEPARATOR,new byte[]{'\\',0}));
            final List<Region> callbacks=new ArrayList<>();int changes=in.readInt();for(int k=0;k<changes;k++)callbacks.add(new Region(in.readInt(),blob(in)));
            byte[][] expected=new byte[4][];for(int k=0;k<4;k++)expected[k]=blob(in);int expectedReturn=in.readInt(),eventCount=in.readInt();List<byte[]> expectedEvents=new ArrayList<>();for(int k=0;k<eventCount;k++)expectedEvents.add(blob(in));final List<byte[]> events=new ArrayList<>();
            Pc1NativePaths.Attributes os=address->{events.add(memory.cstring(address));for(Region r:callbacks)for(int k=0;k<r.bytes.length;k++)memory.write(r.address+k,r.bytes[k]);return attributes;};
            if(entry==0x40e5a0)Pc1NativePaths.buildAsset(memory,args[0],args[1],args[2],args[3],os);
            else if(entry==0x40e870)Pc1NativePaths.buildRoot(memory,args[0],args[1],args[2],args[3],os);
            else if(entry==0x41ce20)Pc1NativePaths.forceExtension(memory,args[0],args[3]);
            else check(Pc1NativePaths.extensionPointer(memory,args[0])==expectedReturn,id+" native extension pointer");
            int[] addresses={0xed0000,0xec0000,0x94c310,0x94c518};for(int k=0;k<4;k++)check(Arrays.equals(memory.bytes(addresses[k],expected[k].length),expected[k]),id+" full byte region"+k);
            boolean same=events.size()==expectedEvents.size();for(int k=0;same&&k<events.size();k++)same=Arrays.equals(events.get(k),expectedEvents.get(k));check(same,id+" attribute call count/raw path");
        }
        check(in.read()==-1,"native path vector trailer");return count;
    }
    public static void main(String[] args)throws Exception{System.out.println("PASS "+run()+" native path checks");}
    private static final String[] VECTORS={
        "",
        "",
        ""
    };
}
